export function relativeLuminance({ r, g, b }: LinearSrgb): number {
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}

export function parseNativePublicEnv(source: EnvSource = readNativePublicEnv()): NativePublicEnv {
  assertNoServerOnlyKeys(source, 'parseNativePublicEnv')
  return parseEnvOrThrow(NativePublicEnvSchema, source, 'native public (EXPO_PUBLIC_*)')
}

export function normalizeTitle(raw: string): string {
  return raw.replace(/\s+/gu, ' ').trim()
}

export function readMiss(resource?: string): AppError {
  return appError.notFound(resource === undefined ? {} : { resource })
}

function applyLocale(locale: Locale): void {
  platform.applyDirection(locale, directionOf(locale))
}

function key(name: string): string {
  return BARE_KEY.test(name) ? name : `'${name}'`
}

export function bucketForAction(name: string): RateLimitBucket | null {
  if (!Object.hasOwn(ACTION_BUCKETS, name)) return WRITE
  return ACTION_BUCKETS[name] ?? null
}

export function errorCopy(error: AppError): string {
  return t(KEY_BY_CODE[error.code] ?? KEY_BY_KIND[error.kind])
}

export function parseMajor(version: string): number | null {
  const match = /^\s*v?(\d+)(?:\.|$)/.exec(version)
  const major = match?.[1]
  return major === undefined ? null : Number(major)
}

export function readOptionalServerEnv(): EnvSource {
  return {
    UPSTASH_REDIS_REST_TOKEN: process.env.UPSTASH_REDIS_REST_TOKEN,
    UPSTASH_REDIS_REST_URL: process.env.UPSTASH_REDIS_REST_URL,
    APP_VERSION: process.env.APP_VERSION,
    MIN_SUPPORTED_CLIENT: process.env.MIN_SUPPORTED_CLIENT,
  }
}

export async function toOutcomeAsync<T>(
  run: () => Promise<T>,
  onThrow?: (cause: unknown) => void,
): Promise<ActionOutcome<T>> {
  try {
    return outcomeOk(await run())
  } catch (cause) {
    onThrow?.(cause)
    return outcomeErr(appError.unknown())
  }
}

export function decodeNotesCursor(token: string): NoteCursor | null {
  if (token.length === 0 || token.length > NOTES_CURSOR_MAX) return null
  const json = fromBase64Url(token)
  if (json === null) return null
  try {
    // Annotated `unknown`, not left as JSON.parse's `any`: an `any` flowing
    // into a zod parse silently disables every downstream type check the
    // lint rules exist to enforce.
    const decoded: unknown = JSON.parse(json)
    return CursorKey.parse(decoded)
  } catch {
    return null
  }
}

export function encodePushCursor(key: PushCursor): string {
  const safe = PushCursorKey.parse(key)
  return toBase64Url(JSON.stringify({ createdAt: safe.createdAt, id: safe.id }))
}

function shapedCode(data: unknown): string | null {
  if (typeof data !== 'object' || data === null || !('code' in data)) return null
  const code = (data as { readonly code?: unknown }).code
  return typeof code === 'string' ? code : null
}

function bearerToken(request: Request): string | null {
  const header = request.headers.get('authorization')
  if (header === null) return null
  return BEARER_SCHEME.exec(header)?.[1] ?? null
}

function orgGate(activeOrg: OrgSummary | null): ActionOutcome<OrgSummary> {
  return activeOrg === null
    ? outcomeErr(
        appError.forbidden({
          code: 'org_context_required',
          message: 'an active organization is required',
        }),
      )
    : outcomeOk(activeOrg)
}

function emitColors(lines: string[]): void {
  lines.push('colors: {')
  for (const token of SEMANTIC_TOKENS) {
    lines.push(`  ${key(token)}: 'var(${colorVarName(token)})',`)
  }
  lines.push('},')
}

function assertKeysAreDistinct(server: ServerEnv, web: WebPublicEnv): void {
  if (server.SUPABASE_SERVICE_ROLE_KEY !== web.NEXT_PUBLIC_SUPABASE_PUBLISHABLE) return
  throw new Error(
    '@app/env: NEXT_PUBLIC_SUPABASE_PUBLISHABLE holds the SAME value as ' +
      'SUPABASE_SERVICE_ROLE_KEY. The elevated key bypasses row security and a NEXT_PUBLIC_ ' +
      'name is compiled into the bundle served to every browser — this deployment would hand ' +
      'every tenant read and write access to every other. Rotate the elevated key (the value ' +
      'has to be assumed leaked) and set the PUBLISHABLE key here instead.',
  )
}

