export function ThemeProvider({ theme, children, className, testID }: ThemeProviderProps) {
  const value = useMemo(() => ({ theme }), [theme])
  return (
    <ThemeContext.Provider value={value}>
      <div data-theme={theme} data-testid={testID} className={cn('bg-canvas text-ink', className)}>
        {children}
      </div>
    </ThemeContext.Provider>
  )
}

export function oklchToHex(color: Oklch): string {
  const linear = oklchToLinearSrgb(color)
  if (!inSrgbGamut(linear)) {
    throw new Error(
      `oklch(${color.l} ${color.c} ${color.h}) is outside the sRGB gamut — retune the ramp value`,
    )
  }
  const bytes = [linear.r, linear.g, linear.b].map(channelToByte)
  return `#${bytes.map((b) => b.toString(16).padStart(2, '0')).join('')}`
}

export function startSpan(logger: Logger, name: string, fields: LogFields = {}): Span {
  const startedAt = logger.now()
  let settled: number | null = null

  const end = (endFields: LogFields = {}): number => {
    if (settled !== null) return settled
    const durationMs = Math.max(0, Math.round(logger.now() - startedAt))
    settled = durationMs
    logger.info(`span ${name}`, { ...fields, ...endFields, span: name, durationMs })
    return durationMs
  }

  return { name, end }
}

export async function withSpanAsync<T>(
  logger: Logger,
  name: string,
  run: () => Promise<T>,
  fields: LogFields = {},
): Promise<T> {
  const span = startSpan(logger, name, fields)
  try {
    const result = await run()
    span.end({ outcome: 'ok' })
    return result
  } catch (cause) {
    span.end({ outcome: 'threw', cause })
    throw cause
  }
}

export function createRateLimiter(options: {
  readonly onMemoryFallback?: () => void
  readonly onUnavailable: (error: unknown) => void
  // SOURCE: docs/adr/20260204-rate-limiting.md (the host may tighten the REST deadline)
  readonly timeoutMs?: number
  readonly upstashToken?: string | undefined
  readonly upstashUrl?: string | undefined
}): RateLimiter {
  const { upstashToken, upstashUrl } = options
  if (upstashUrl != null && upstashUrl !== '' && upstashToken != null && upstashToken !== '') {
    return withFailOpen(
      createUpstashRateLimiter({
        // Spread rather than `timeoutMs: options.timeoutMs`: under
        // exactOptionalPropertyTypes an explicit `undefined` is NOT the same as an absent
        // key, and passing one would defeat the adapter's own default.
        // SOURCE: docs/adr/20260204-rate-limiting.md
        ...(options.timeoutMs === undefined ? {} : { timeoutMs: options.timeoutMs }),
        token: upstashToken,
        url: upstashUrl,
      }),
      options.onUnavailable,
    )
  }
  options.onMemoryFallback?.()
  return withFailOpen(createMemoryRateLimiter(), options.onUnavailable)
}

export function chunkCookieValue(value: string, limit: number = CHUNK_BYTES): readonly string[] {
  const chunks: string[] = []
  let current = ''
  let size = 0
  for (const character of value) {
    const bytes = utf8Bytes(character.codePointAt(0) ?? 0)
    if (size + bytes > limit && current !== '') {
      chunks.push(current)
      current = ''
      size = 0
    }
    current += character
    size += bytes
  }
  chunks.push(current)
  return chunks
}

export function createBrowserSupabaseClient(
  options: BrowserClientOptions = {},
): SupabaseBrowserClient {
  const { publishableKey, url } = options.credentials
    ? requireCredentials(options.credentials, 'the caller')
    : publicCredentials()

  // eslint-disable-next-line @typescript-eslint/no-unsafe-return -- @supabase/supabase-js's createClient is untyped by deliberate doctrine (types.ts: no Database generic; rows are re-parsed at the DAL exit). This return is the intentional untyped-client boundary.
  return createClient(url, publishableKey, {
    auth: {
      // The browser is the one host where an unattended refresh timer is right:
      // the tab is alive, the user is present, and a session that lapses mid-use
      // is a form that loses its contents on submit.
      autoRefreshToken: true,
      // Magic-link and OAuth returns land back on the app with the credential in
      // the URL. False here means the client ignores it and the user bounces
      // back to sign-in holding a token nobody read.
      detectSessionInUrl: true,
      // PKCE, not implicit. The implicit flow puts the token in the URL
      // FRAGMENT, where it lands in browser history, in `Referer` on the next
      // navigation, and in any analytics script that reports `location.href`.
      // PKCE returns a single-use code bound to a verifier this client holds.
      // SOURCE: https://www.rfc-editor.org/rfc/rfc9700 (OAuth 2.0 security best
      // current practice: the implicit grant SHOULD NOT be used)
      flowType: 'pkce',
      persistSession: true,
      ...(options.storage === undefined ? {} : { storage: options.storage }),
    },
  })
}

export function parseProbeBudgets(params: Readonly<Record<string, ParamValue>>): ProbeBudgets {
  return {
    tabSwitchMs: positiveNumber(params['tabSwitchMs'], DEFAULT_PROBE_BUDGETS.tabSwitchMs),
    actionsOpenMs: positiveNumber(params['actionsOpenMs'], DEFAULT_PROBE_BUDGETS.actionsOpenMs),
    frameDropMax: positiveNumber(params['frameDropMax'], DEFAULT_PROBE_BUDGETS.frameDropMax),
    runs: Math.round(positiveNumber(params['runs'], DEFAULT_PROBE_BUDGETS.runs)),
  }
}

function redactObject(value: object, depth: number, seen: WeakSet<object>): unknown {
  if (Array.isArray(value)) {
    return (value as readonly unknown[]).map((item) => redactValue(item, depth + 1, seen))
  }

  // An Error is the most likely non-plain value here: it is what the kernel's
  // `toOutcome(run, onThrow)` hands over. Name and message only — a stack is not
  // enumerable (JSON.stringify drops it anyway) and routinely carries absolute
  // build-machine paths, which is not information this seam should forward to a
  // client transport.
  if (value instanceof Error) return { name: value.name, message: value.message }

  // A Date is JSON-safe already, but only via its own toJSON; making the ISO
  // string explicit means the record's own JSON-safety does not depend on a
  // sink calling JSON.stringify rather than inspecting the object.
  if (value instanceof Date) return value.toISOString()

  // Maps and Sets have no own enumerable properties, so the generic walk below
  // would report them as `{}` — an empty object where there was data is worse
  // than a tag that says how much data there was.
  if (value instanceof Map) return `[Map(${String(value.size)})]`
  if (value instanceof Set) return `[Set(${String(value.size)})]`

  // The cast is what `Object.entries` cannot express for a bare `object` (it
  // would hand back `any` values, and an `any` inside the redaction pass is a
  // hole in exactly the wrong place). Sound here: every remaining case is a
  // walkable object, and each value is immediately re-entered as `unknown`.
  const out: Record<string, unknown> = {}
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    if (nested === undefined) continue // absent in, absent out — see @app/errors
    out[key] = isSensitiveKey(key) ? REDACTED : redactValue(nested, depth + 1, seen)
  }
  return out
}

export function Providers({ children }: { readonly children: ReactNode }): ReactNode {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            // A short window, not zero and not minutes. Zero refetches on every mount and
            // makes React's development double-render look like a network storm; long values
            // show a user their own stale writes after a mutation. Thirty seconds is long
            // enough to absorb navigation, short enough that nothing looks frozen.
            // SOURCE: docs/harness/README.md (tuning constants are stated, not defaulted)
            staleTime: 30_000,
            // Refetching whenever a window regains focus is a sensible default for a
            // dashboard and a wasteful one for a form the user tabbed away from mid-edit.
            // Off globally; opt in per query where freshness actually matters.
            refetchOnWindowFocus: false,
          },
        },
      }),
  )

  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
}

export async function ensurePersonalOrgAction(): Promise<ActionOutcome<readonly OrgSummary[]>> {
  // The rate-limit seam. FIRST, before any work and before the identity round trip: an
  // unauthenticated flood at a Server Action id is the flood worth stopping, and a limit
  // applied after `getUser()` still pays an auth call per abusive request.
  const limited = await enforceActionRateLimit('ensurePersonalOrgAction')
  if (limited !== null) return limited
  const result = await runEnsurePersonalOrg()
  if (result.data !== undefined) return result.data
  if (result.serverError !== undefined) return outcomeErr(result.serverError)
  return outcomeErr(appError.unknown({ message: 'Could not create your workspace.' }))
}

export async function requireOrgContext(orgSlug: string): Promise<ActionOutcome<OrgContextValue>> {
  const client = await createRequestScopedClient()
  const session = await resolveHostSession(client)
  if (session === null) return outcomeErr(appError.unauthorized())

  const wanted = orgSlug.trim().toLowerCase()
  const org = session.orgs.find((o) => o.slug === wanted)
  if (org === undefined) {
    return outcomeErr(
      appError.forbidden({
        code: 'org_context_required',
        message: 'an active organization is required',
      }),
    )
  }
  return outcomeOk({ client, org, orgs: session.orgs, userId: session.actor.userId })
}

-- ─────────────────────────────────────────────────────────────────────────────
-- The RPCs
-- ─────────────────────────────────────────────────────────────────────────────

-- The JIT door. Reads the RAW seat (this function MINTS what the effective helpers
-- consult, so it cannot itself consult them), applies both ASD windows at the
-- threshold, and mints or refreshes a one-hour elevation. Returns the expiry so the
-- UI can show "elevated until …".
CREATE FUNCTION public.elevate(p_org_id uuid)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_caller uuid := (SELECT private.caller_id());
  v_raw_rank smallint;
  v_revalidated_at timestamptz;
  v_last_active timestamptz;
  v_expires timestamptz;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT m.role_rank, m.revalidated_at INTO v_raw_rank, v_revalidated_at
    FROM public.memberships m
   WHERE m.user_id = v_caller AND m.org_id = p_org_id;
  IF v_raw_rank IS NULL OR v_raw_rank < 30 THEN
    RAISE EXCEPTION 'no privileged seat in this org' USING ERRCODE = '42501';
  END IF;

  -- The seat's last privileged ACTIVITY: the elevation trail's stamp when one
  -- exists, else the seat's own revalidation. Both windows are judged at this one
  -- threshold, because both have the same remedy.
  -- GREATEST, like LEAST above, is SQL syntax rather than a catalog function.
  SELECT greatest(
           coalesce((SELECT e.last_privileged_at
                       FROM public.admin_elevations e
                      WHERE e.user_id = v_caller AND e.org_id = p_org_id),
                    v_revalidated_at),
           v_revalidated_at)
    INTO v_last_active;

  -- RAP-02: revalidated within 12 months. RAP-03: active within 45 days. ASD's
  -- verbatim numbers — see the header for why no others may appear here.
  IF v_revalidated_at <= pg_catalog.now() - interval '12 months'
     OR v_last_active < pg_catalog.now() - interval '45 days' THEN
    IF v_raw_rank >= 40 THEN
      -- The deadlock-breaker: there is no rank above owner to revalidate an owner,
      -- so a lapsed rank-40 seat revalidates ITSELF — gated on a verified second
      -- factor, through the one narrow policy that admits exactly this write.
      IF NOT (SELECT private.mfa_satisfied()) THEN
        RAISE EXCEPTION 'this seat has lapsed (12-month revalidation / 45-day activity); revalidating an owner seat requires a verified second factor (aal2) — complete an MFA challenge and retry'
          USING ERRCODE = '42501';
      END IF;
      UPDATE public.memberships SET revalidated_at = pg_catalog.now()
       WHERE user_id = v_caller AND org_id = p_org_id AND role_rank = 40;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'could not revalidate the owner seat' USING ERRCODE = '42501';
      END IF;
    ELSE
      RAISE EXCEPTION 'this seat has lapsed (12-month revalidation / 45-day activity) — ask an owner to run revalidate_member for you'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO public.admin_elevations (user_id, org_id, session_id)
  VALUES (v_caller, p_org_id, (SELECT private.caller_session()))
  ON CONFLICT (user_id, org_id) DO UPDATE
    SET expires_at = pg_catalog.now() + interval '1 hour',
        last_privileged_at = pg_catalog.now(),
        session_id = excluded.session_id
  RETURNING expires_at INTO v_expires;
  RETURN v_expires;
END;
$$;
